package org.jlinalg.genetics;

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.LinkedHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import jdistlib.math.MathFunctions;
import org.jlinalg.genetics.FumaFisherExact.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class FumaFisherExactTest {
    private static final Runnable CHECK=()->{};
    private static Result fit(Counts counts,int add){return FumaFisherExact.test(counts,new Options(add,.95,Limits.defaults()),CHECK);}
    private static List<String[]> resource(String name)throws Exception {
        try(var input=FumaFisherExactTest.class.getResourceAsStream("/fuma-fisher-exact/"+name)){
            assertNotNull(input);try(var reader=new BufferedReader(new InputStreamReader(input,StandardCharsets.UTF_8))){return reader.lines().skip(1).map(line->line.split("\t",-1)).toList();}
        }
    }
    private static double numeric(String value){return switch(value){case "Inf"->Double.POSITIVE_INFINITY;case "-Inf"->Double.NEGATIVE_INFINITY;default->Double.parseDouble(value);};}
    private static void same(double expected,double actual,String context){if(expected==0||!Double.isFinite(expected))assertEquals(expected,actual,context);else assertTrue(Double.isFinite(actual)&&Math.abs(actual-expected)/Math.abs(expected)<=2e-14,()->context+": expected "+expected+", observed "+actual+", relative "+Math.abs(actual-expected)/Math.abs(expected));}
    @Test void allOriginalRCountOddsConfidenceAndIndependentLogReferenceRowsAgree()throws Exception {
        var input=resource("input.tsv");var reference=resource("reference.tsv");assertEquals(1396,input.size());assertEquals(input.size(),reference.size());
        var boundaries=new LinkedHashMap<String,String[]>();for(var row:resource("numerical-boundaries.tsv"))boundaries.put(row[0]+"\t"+row[1],row);assertEquals(11,boundaries.size());String[] fields={"p","log_p","OR","lower","upper"};
        for(int i=0;i<input.size();i++){
            var row=input.get(i);var expected=reference.get(i);assertEquals(row[0],expected[0]);var counts=new Counts(Long.parseLong(row[1]),Long.parseLong(row[2]),Long.parseLong(row[3]),Long.parseLong(row[4]));var result=FumaFisherExact.test(counts,new Options(Integer.parseInt(row[5]),Double.parseDouble(row[6]),Limits.defaults()),CHECK);
            double[] actual={result.pValue(),result.logPValue(),result.oddsRatio(),result.lowerConfidence(),result.upperConfidence()};for(int j=0;j<actual.length;j++){double wanted=numeric(expected[j+1]);var boundary=boundaries.get(row[0]+"\t"+fields[j]);if(boundary==null)same(wanted,actual[j],row[0]+" field "+(j+1));else{assertTrue(row[0].startsWith("synthetic-"));assertEquals(wanted,numeric(boundary[2]));assertTrue(Double.isFinite(actual[j])&&Math.abs(actual[j]-wanted)/Math.abs(wanted)<=Double.parseDouble(boundary[4]),row[0]+" retained arithmetic boundary "+fields[j]);}}
        }
    }
    @Test void explicitPseudocountRetainsBothOriginalAndTestedCounts(){var counts=new Counts(53,105,20,126);var r=fit(counts,1);assertEquals(counts,r.original());assertEquals(new Counts(54,106,21,127),r.tested());assertEquals(1,r.pseudocount());assertEquals(304,r.original().total());assertEquals(308,r.tested().total());assertTrue(r.warnings().stream().anyMatch(s->s.contains("not observed associations")));}
    @Test void addingOneChangesTheActualFixedMarginTest(){var counts=new Counts(53,105,20,126);var raw=fit(counts,0);var added=fit(counts,1);same(5.06912026876196e-5,raw.pValue(),"raw P");same(6.27679302214557e-5,added.pValue(),"added P");same(3.06968525907479,added.oddsRatio(),"added conditional OR");assertNotEquals(raw.oddsRatio(),added.oddsRatio());}
    @Test void conditionalEstimateIsDistinctFromTheSampleCrossProduct(){var counts=new Counts(1,9,11,3);var r=fit(counts,0);assertNotEquals(1.0*3/(9*11),r.oddsRatio());same(.0027594561852200836,r.pValue(),"two-sided P");}
    @Test void sourceDefaultRootToleranceAndParameterizationAreAudited(){assertEquals(.0001220703125,FumaFisherExact.ROOT_TOLERANCE);var r=fit(new Counts(53,105,20,126),1);assertEquals(3,r.roots().size());assertTrue(r.roots().stream().allMatch(RootAudit::inverse));assertTrue(r.roots().stream().allMatch(a->a.root()>0&&a.root()<=1&&a.bracketWidth()>=0&&a.iterations()>=0));assertTrue(r.warnings().stream().anyMatch(s->s.contains("not a relative accuracy guarantee")));}
    @Test void finiteLogProbabilitySurvivesExactTestProbabilityUnderflow(){var r=fit(new Counts(2000,0,0,2000),0);assertEquals(0,r.pValue());assertTrue(Double.isFinite(r.logPValue()));same(Math.log(2)-MathFunctions.lchoose(4000,2000),r.logPValue(),"independent diagonal log tail");assertEquals(Double.POSITIVE_INFINITY,r.oddsRatio());assertEquals(Double.POSITIVE_INFINITY,r.upperConfidence());assertTrue(r.warnings().stream().anyMatch(s->s.contains("not an exact zero probability")));}
    @Test void nullTableRetainsAnUnidentifiableSourceBoundaryInsteadOfBiologicalEvidence(){var r=fit(new Counts(0,0,0,0),0);assertEquals(1,r.pValue());assertEquals(0,r.logPValue());assertEquals(0,r.oddsRatio());assertEquals(0,r.lowerConfidence());assertEquals(Double.POSITIVE_INFINITY,r.upperConfidence());assertEquals(1,r.supportStates());assertTrue(r.warnings().stream().anyMatch(s->s.contains("unidentifiable")));}
    @Test void pseudocountOnlyGroupsRetainAnExplicitEmptyOriginalWarning(){var r=fit(new Counts(0,0,57,340),1);assertEquals(0,r.original().finerNovel()+r.original().finerKnown());assertEquals(2,r.tested().finerNovel()+r.tested().finerKnown());assertTrue(r.warnings().stream().anyMatch(s->s.contains("EMPTY ORIGINAL GROUP")));}
    @Test void perfectSeparationRetainsBoundaryOddsAndCentralConfidenceLimits(){var positive=fit(new Counts(4,0,0,7),0);assertEquals(Double.POSITIVE_INFINITY,positive.oddsRatio());assertEquals(Double.POSITIVE_INFINITY,positive.upperConfidence());assertTrue(positive.lowerConfidence()>0);var negative=fit(new Counts(0,4,7,0),0);assertEquals(0,negative.oddsRatio());assertEquals(0,negative.lowerConfidence());assertTrue(Double.isFinite(negative.upperConfidence()));same(positive.pValue(),negative.pValue(),"row reversal P");}
    @Test void confidenceCoverageIsExplicitAndChangesIntervals(){var counts=new Counts(7,9,11,3);var narrow=FumaFisherExact.test(counts,new Options(0,.8,Limits.defaults()),CHECK);var wide=FumaFisherExact.test(counts,new Options(0,.99,Limits.defaults()),CHECK);assertEquals(narrow.pValue(),wide.pValue());assertEquals(narrow.oddsRatio(),wide.oddsRatio());assertTrue(wide.lowerConfidence()<narrow.lowerConfidence());assertTrue(wide.upperConfidence()>narrow.upperConfidence());}
    @Test void balancedCompleteTailIsProbabilityOneAndLogZero(){var r=fit(new Counts(10,10,10,10),0);assertEquals(1,r.pValue());assertEquals(0,r.logPValue());assertEquals(1,r.oddsRatio());}
    @Test void sourceSwapsPreserveTheFixedMarginTwoSidedProbability(){var r=fit(new Counts(7,9,11,3),1);var transposed=fit(new Counts(7,11,9,3),1);same(r.pValue(),transposed.pValue(),"transpose P");same(r.oddsRatio(),transposed.oddsRatio(),"transpose conditional OR");}
    @Test void testedPopulationBudgetIncludesEveryAddedCell(){var counts=new Counts(53,105,20,126);assertThrows(IllegalArgumentException.class,()->FumaFisherExact.test(counts,new Options(1,.95,new Limits(307,200000,100000000,1000)),CHECK));assertDoesNotThrow(()->FumaFisherExact.test(counts,new Options(1,.95,new Limits(308,200000,100000000,1000)),CHECK));}
    @Test void completeSupportBudgetIsCheckedBeforeAllocationOrTruncation(){var counts=new Counts(10,10,10,10);var failure=assertThrows(IllegalArgumentException.class,()->FumaFisherExact.test(counts,new Options(0,.95,new Limits(1000,20,100000000,1000)),CHECK));assertTrue(failure.getMessage().contains("no states were truncated"));assertEquals(21,fit(counts,0).supportStates());}
    @Test void operationBudgetRefusesTheWholeResult(){var failure=assertThrows(IllegalArgumentException.class,()->FumaFisherExact.test(new Counts(10,10,10,10),new Options(0,.95,new Limits(1000,100,1,1000)),CHECK));assertTrue(failure.getMessage().contains("operation budget exceeded"));}
    @Test void unconvergedRootsFailWithTheNamedIterationCause(){var failure=assertThrows(IllegalArgumentException.class,()->FumaFisherExact.test(new Counts(53,105,20,126),new Options(1,.95,new Limits(1000,1000,100000000,1)),CHECK));assertTrue(failure.getMessage().contains("no unconverged estimate was admitted"));}
    @Test void initialAndInCalculationCancellationAreCooperative(){assertThrows(IllegalStateException.class,()->FumaFisherExact.test(new Counts(1,2,3,4),new Options(0,.95,Limits.defaults()),()->{throw new IllegalStateException("cancelled before work");}));var calls=new AtomicInteger();assertThrows(IllegalStateException.class,()->FumaFisherExact.test(new Counts(1000,20,20,1000),new Options(0,.95,Limits.defaults()),()->{if(calls.incrementAndGet()>2)throw new IllegalStateException("cancelled in support");}));assertTrue(calls.get()>2);}
    @Test void negativeNonfiniteAndOverflowingInputsNeverBecomeTables(){assertThrows(IllegalArgumentException.class,()->new Counts(-1,2,3,4));for(double level:List.of(0.0,1.0,Double.NaN,Double.POSITIVE_INFINITY))assertThrows(IllegalArgumentException.class,()->new Options(0,level,Limits.defaults()));assertThrows(IllegalArgumentException.class,()->new Options(-1,.95,Limits.defaults()));assertThrows(ArithmeticException.class,()->fit(new Counts(Long.MAX_VALUE,1,0,0),0));assertThrows(ArithmeticException.class,()->fit(new Counts(Long.MAX_VALUE,0,0,0),1));}
    @Test void missingAndInvalidCapacitiesAreRefused(){assertThrows(IllegalArgumentException.class,()->FumaFisherExact.test(null,new Options(0,.95,Limits.defaults()),CHECK));assertThrows(IllegalArgumentException.class,()->FumaFisherExact.test(new Counts(1,2,3,4),null,CHECK));assertThrows(IllegalArgumentException.class,()->FumaFisherExact.test(new Counts(1,2,3,4),new Options(0,.95,Limits.defaults()),null));assertThrows(IllegalArgumentException.class,()->new Limits(0,1,1,1));assertThrows(IllegalArgumentException.class,()->new Limits(1,0,1,1));assertThrows(IllegalArgumentException.class,()->new Limits(1,1,0,1));assertThrows(IllegalArgumentException.class,()->new Limits(1,1,1,100001));}
    @Test void immutableResultsPreserveRootAndWarningEvidence(){var r=fit(new Counts(53,105,20,126),1);assertThrows(UnsupportedOperationException.class,()->r.roots().clear());assertThrows(UnsupportedOperationException.class,()->r.warnings().clear());assertTrue(r.operations()>r.supportStates());assertTrue(r.warnings().stream().allMatch(s->s.contains("Required action:")));}
}
